-- GENERATED by `wfj generate` from data/quest/quest-0093.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("quest", {
  [93036] = { "教団への潜入", "Shen'dar VillageのSania Silverstreamと話してください。", "知っているかどうかは分からないが、あそこにいるSania SilverstreamはAl'Akethの「宣教師」だ。奴らは普通の宗教団体のふりをして、害のなさそうな使者をあちこちに送って信者を集めている。教団との直接の衝突を避けるために、これまではSaniaを大目に見てきたが、見せかけの平和がこれ以上長く続かないのは明らかだ。\n\n君はここに来たばかりで、ほとんどの者に顔を知られていない。だから、Saniaを利用して教団に近づき、奴らが村に対して何を企んでいるのか探れないか試してほしい。", nil, "ごきげんよう、子よ。私の名はSania Silverstream、Order of the Al'Akethの見習い祭司です。我らが君主、Windlord Al'Akirについてもっと知りたいですか？\n\nWindlordの食卓には、正しき者と悔い改めた者のための席がいつでもあるのです。", 0xbb1fd4b2, 0x82bd3020, 0x59a588f5, nil, 0x23ca2220, "...m." },
  [93065] = { "戦いへの備え", "Gustberry LowlandsのValennia Stormfistと話してください。", "Peacekeepersが動員され、我々は皆出発の準備を整えている。必要な準備を済ませたら、町から北へ出る東の道で我々と合流してくれ。出発前に、全員と最後の確認を1回行う。", nil, "これ以上ないほど準備は整った。", 0x5db1f556, 0xd94373fd, 0x8619e90a, nil, 0xda1d39ff, "...m." },
  [93089] = { "この先に待つもの", "Zephras Isleを発つ準備ができたら、Elaadrin Evengaleと話してください。", "Elaadrinに、High Orderと、君の新しい友である「Kirin Tor」がZephras Isleのためにしてくれたすべてのことへの感謝を伝えてほしい。High Orderが島を離れる計画は承知している。君たちの結社のこの遠征には、私の祝福と幸運の祈りがある。\n\nHigh Orderが見つける秘術の解決策が何であれ、ここ数年我々に欠けていた安定を本当にもたらしてくれることを願うばかりだ。君も彼らと行くつもりなら……まあ、彼の使命はそれだけ力強いものになるだろう。\n\n風が共にあらんことを、{name}。", nil, "我々の遠征にHigh Elder Shadowsongの祝福があると聞いてうれしく思います。教団は打ち倒され、準備も整いました。ついにその時が来たと思います。\n\nAnsiremは、Dalaranの都とZephras Isleの間で安定したskycutterの輸送を実現するために、熱心に働いてくれました。できる限りの試験は済ませました。我々の先遣隊が出発する時が来たのです。", 0x50a257df, 0xb2d66ffb, 0x327a8719, nil, 0xd86a7736, "...m." },
  [93090] = { "この先に待つもの", "Zephras Isleを発つ準備ができたら、Ayessa Dawnsingerと話してください。", "Windshapersと、この「Earthen Ring」から来たあなたの新しい友が、Zephras Isleのためにしてくれたすべてのことに、私からの感謝をAyessaに伝えてください。Windshapersのシャーマンたちを連れて島を離れる計画は承知しています。あなた方の教団には、この遠征への私の祝福と幸運の祈りを送ります。\n\nWindshapersがどんな解決策を見つけるにせよ、ここ何年も私たちに欠けていた安定を本当にもたらしてくれることを願うばかりです。\n\n風があなたと共にありますように、{name}。", nil, "我々の遠征にHigh Elder Shadowsongの祝福があると聞いてうれしく思う。教団は打ち倒され、準備も整った。ついにその時が来たと思う。\n\nMulnは、Zephras Isleと、Earthen Ringが拠点とするMulgoreという地の間で安定したskycutterの輸送を実現するために、熱心に働いてくれた。我々は試験航行を続けていて、仲間の一部はすでに向こう側で待っている。", 0x50a257df, 0x42ef0bb4, 0xfa29d4a6, nil, 0xeaba7e66, "...m." },
  [93159] = { "奇妙な隠者", "Shadowgale ForestのStrange Hermitと話し、彼についてもっと知ってください。", "あ、えっと……こ、こんにちは、いや、その、やあ！ご、ご挨拶を、というか！ごめんなさい……その、ほかの人と実際に話すのは、すごく久しぶりで。ちょっと慣れていないみたいです。\n\n<奇妙なフードの人物は、あなたの前で居心地悪そうに身じろぎする。>\n\nそれで、えっと、その……今日はどんな一日ですか？", nil, "……それについて言えるのは、だいたいそれくらいかな。ここに来る前は、えっと、どこか別の場所にいたんだ。今はここにいて、友達もいるし、自分の物もある。つ、つまり、自分で作った物のことだけど。必要なのはそれくらいかな。とにかく、必要なのはそれだけだと思う。\n\nでも、言っておきたいんだけど、話し返してくれる相手と話せるのはうれしいよ。森の精霊たちも頑張ってはくれるけど、結局は僕に向かって歌い出しちゃうんだ。それはそれでいいんだけど、し、刺激的な会話とは言えないよね。", 0xc281d56b, 0x91510117, 0x813fe37d, nil, 0xf694abb5, "...m." },
  [93160] = { "森の恵み", "Shadowgale ForestでShadowgale Acornを$N1個集めてください。", "話しに寄ってくれて本当に嬉しいです！ も、もし手伝ってくれるなら、森の地面からどんぐりを集めるのを少し手伝ってほしいんです。近くのはほとんど集めたんですけど、森にはraptorみたいな鳥がすごくたくさんいて。外は危ないし、巨大な鳥のお昼ごはんにはなりたくないんです！\n\nだから、もしよかったら、集めてきてもらえませんか？ そうしてくれたら、何かおいしいものを作りますね！", "うーん、このドングリでこしらえる料理、きっと気に入ってもらえると思うよ！", "ありがとう、旅の人！焼いたらこれがとってもおいしいって分かるよ！\n\nちょっと失礼するね。これを手早く作るのに、そう時間はかからないから。", 0x4aa75777, 0x076dacd0, 0xb98c76cc, 0xd9fab18b, 0xc1c8b911, "....." },
  [93165] = { "慈悲は聞く耳を持たぬ者に", "Shadowgale Forest、Shrine of Akir、またはGustberry LowlandsのAl'Aketh信者から、Al'Aketh Cultist's Earsを10個集めて下さい。", "Al'Akethは我らの集落に大いなる悲劇をもたらした。血は血で償わせねばならぬ。\n\nよそ者よ、そなたに申し出がある。この呪われた教団員どもと争うことがあれば、倒した者の耳を持ってくるがよい。持ち帰った耳ごとに金で報いよう。そして、そなたが真の友であると証明すれば、いずれNightclawの秘密に触れることも許そう。", "この島の教団員を一人残らず、その喉笛をこの牙で食い破るまで、私は休まない。", "見事な働きだ。教団を排除して起こるのは良いことだけだ。これで、Nightclawは侮れない相手であり、我々の恨みは深いのだと思い知らせることができればいいが。\n\n教団を相手にするとなれば、お前もさぞ骨が折れることだろう。もっと耳を集めたら、ここへ持ってこい。", 0x67167132, 0x39b5cde8, 0xf3604d96, 0x3dfb4bed, 0x83d85581, "....." },
  [93172] = { "Hollowsの解放", "Shadowgale ForestのWind Hollowsを10個破壊してください。", "この島のエルフのほとんどは、この森には幽霊が出ると思っていて、それは間違いじゃない。\n\n北東の古い遺跡には、幽霊のような奇妙な霊たちが集まっている。夜によっては、彼らが「歌っている」のがほとんど聞こえるほどだ。今までに聞いたどんな歌とも違うけど、確かに歌で、それが……とにかく悲しいんだ。\n\nなぜかは分からないけど、いつかあそこで何か恐ろしいことが起きて、霊たちがどういうわけかそこに閉じ込められているんだと思う。勇気があるなら、彼らを解放する手助けをしてくれないかな？", nil, "ありがとう、旅の人。", 0x0e18dc30, 0x1267d2ac, 0xe5c300d2, nil, 0x66dd9c71, "...m." },
  [93173] = { "（未使用）Rusty Gadget", "Shadowgale ForestのThe Strange HermitにRusty Gadgetを返して下さい。", "<Wind Hollowをまとめていた渦巻く気流が消えはじめると、小さな金属の装置が足元に転がり落ちた。何かの機械仕掛けの道具のようだ。The Strange Hermitはまだ装備がいくつか見つかっていないと言っていた。これに興味を持つかもしれない。>", nil, nil, 0xd8c783cf, 0x333107c8, 0xd88d703f, nil, nil, "...mm" },
  [93317] = { "カニの季節", "Windsong Crawler Meatを6つ集めてください。", "Windsong Crawlersをご存じですか？ このカニはここZephrasのWindsong Lakeにしかいなくて、一年のうち数週間しか獲れないんです。\n\n最近の教団の活動のせいで湖まで獲りに行けなくて、時期がどんどん終わりに近づいています。行って少し集めてきてくれたらありがたいです。たいてい湖の周りの岸辺や川沿いにいます。\n\nでも気をつけてくださいね、見た目より凶暴ですから！", "Windsong Crawlerの肉はここではありふれているが、AnvilasやSiroccasの島々ではちょっとしたごちそうだったんだ。空の流れがまだ開いていた頃は、Shen'dramarやNew Eldre'naarへ足を運ぶたびに、地元の連中がこれを求めて押し寄せてきたもんさ。\n\nああいう場所には、もう……そうだな……ずいぶん長いこと行けていない。", "風よ、なんて素晴らしい肉だろう！\n\n本当にありがとう、{class}。", 0x6f40d8c7, 0x3826218b, 0xb3597e4b, 0x9e47a279, 0x2bc6df4e, "....." },
  [93318] = { "お尋ね者：Vulgara the Insatiable", "Shen'dar HighlandsでVulgara the Insatiableを倒し、その首をDanarii Bellowveilに届けてください。", "PeacekeepersのConstable Aondaの命により、ここに高地の災厄、Vulgara the Insatiableに懸賞金をかける。最後に目撃されたのはShen'dar Villageのすぐ南西の丘の上。翼を持つこのvuldrenの怪物は非常に危険であり、慎重に近づくこと。\n\n報酬を受け取るには、その獣の首をDanarii Bellowveilに届けること。", "やり遂げた証として、その生き物の首が必要だ。", "教団と高地の山賊だけでも手一杯だというのに、巨大なvuldrenにまで市民を脅かされてはたまらない。今日、あなたは素晴らしいことをしてくれた。約束どおり、これが報酬だ。", 0x26deadde, 0x95335eb7, 0x44a54b33, 0x7e44c040, 0xedf3a0ac, "....." },
  [93319] = { "Pilfered Windstones", "Shen'dar HighlandsのHighlands Banditsから、Pilfered Windstonesを10個集めてください。", "ここZephrasでは、日々の暮らしにますますwindstoneを頼るようになっていて、非常時に備えて予備を蓄えておくようにしている。ところが最近、蓄えの中からいくつかなくなっていることに気づいた。\n\n最近捕まえた山賊たちがwindstoneを持っていたから、蓄えが減っているのは奴らのせいだとにらんでいる。\n\n北の山賊の洞窟の近くに行くことがあったら、何人か痛い目に遭わせて、盗まれたwindstoneをいくつか取り返してきてくれないか？", "このこそ泥どもは、何か月も前から私たちの物資に忍び込んでいたんだろう。あの盗賊の洞窟をきっぱり一掃する襲撃隊を組むようAondaを説得しようとしたが、彼女は村からわずかな治安維持の者たちを引き離したがらなかった。\n\n南のFalaath Villageで教団員の数が増えている今、それを責めるわけにもいかないだろうな。", "ありがとう、{class}。これで当面はしのげるはずだ。だが、補給路をすぐに立て直せなければ、盗まれた風の石が少しばかりなんてことは、心配事のうちにも入らなくなるだろう。", 0x41d7b2ca, 0x098aea7b, 0x414845c0, 0x9132cdaf, 0x4e8fd502, "....." },
  [93320] = { "塔の防衛", "Gustberry Lowlandsの東の見張り塔にいるYorana Windyreedに報告してください。", "町のすぐ外にあるパイロンの見張り塔を教団が攻撃しているという知らせが入った！ ここにいる数少ない予備の治安維持隊を送り、敵の後方線を突破して守備隊を救援させようとしているが、少しでも助けが増えれば、あそこにいる仲間たちの生死を分けるかもしれない。\n\nすぐに東の見張り塔へ向かい、できる限りの援護をしてくれ。\n\n救援部隊は私の副官Yorana Windyreedが率いている。彼女がまだ生きていれば、どう助けるのが最善か教えてくれるだろう。", nil, "今のところは持ちこたえているが、敵の数の方が多く、こちらの戦士たちは疲れ始めている。膠着状態を打ち破るために何か手を打たねばならない。それも急いでだ。", 0x0a49deab, 0x7f44b2b4, 0x98ee9961, nil, 0xbdc9cc11, "...m." },
  [93459] = { "さらなるAl'Akethの耳", "Shadowgale Forest、Shine of Akir、またはGustberry LowlandsにいるAl'Akethから、Al'Aketh Cultist's Earsを10個集め、Shadowgale ForestのVayn Moonclawに届けてください。", "Al'Aketh cultは普段、この森に幽霊が出るという噂を恐れて近づかない……その噂は我々が喜んで保っているものだ。我が結社のドルイドたちは、ここShadowgaleで静かで平和な暮らしを望んでいるだけなのに、奴らはそれを脅かしている。\n\n我々の多くが恐れている。\n\n申し出がある。我々の代わりに教団員と戦い、倒した者の耳を持ってきてくれ。持ち帰った耳ごとに金で報いよう。そして、君が真の友であると証明すれば、いずれ我々の秘密に触れることも許そう。", "<Vaynはあなたにうなずいた。>", "約束どおり、これが報酬だ。", 0x91339b63, 0x4cc2e33c, 0x184326a2, 0xe91596f9, 0x53f5cf99, "....." },
  [93461] = { "Shen'dar Villageへようこそ", "Shen'dar VillageのRathiril SunlanceとCoriella Calmbreezeと話してください。", "君には「High Order」の雰囲気があるね。Highborneの血を引く者は、いつも目に少しきらめきがあるから分かるんだ。ここで本格的に働いてもらう前に、ここに住むHigh Orderの長老、Rathiril Sunlanceに挨拶しておくといい。ここ本館の、私のすぐ角を曲がった所にいるよ。\n\nああ、それとCoriella Calmbreezeにも顔を出しておいて。地元の宿屋をやっていて、必要なら宿と物資を用意してくれる。", nil, "Rathirilには顔を出してきたかい？よし。近頃はHigh OrderとWindshapersの間がかなりぴりぴりしているけど、ここShen'darでは礼儀を保ってるよ。まあ、少なくとも村の中ではね。荒野で起きたことは荒野に置いていくのさ。\n\nそれが済んだなら、あんたは手を動かす仕事を探していそうな顔をしてるね。やってほしいことがいくつかあるんだ。ちょっと働いてみる気はあるかい？", 0x4c9d3c02, 0xe867665b, 0x8517821c, nil, 0xbc58bc08, "...m." },
  [93552] = { "Windstonesの採取", "Thendal GroveのRaw Windstonesから、Windstone Clustersを15個集めてください。", "windstoneはZephras Isleにとって欠かせない資源だ。風そのものの、生の凝縮されたエネルギーを宿しているからな。かつてここZephrasで我々と共に暮らしていた風のエレメンタルたちは何年も前に姿を消し、それ以来、この島を支えている魔法は少しずつ薄れつつある。限界がないわけではないが、windstoneは今でも頼れるエネルギー源で、我々にとって非常に貴重なものだ。\n\nこの木立のあちこちに、未加工のwindstoneが散らばっている。採集するのを手伝ってくれないか？", "やあ、{class}。", "これを本当にありがとうございます。エルフである私たちは皆、魔法と深くつながっています。大いなる錨の柱がこの島に吹き込んだ魔法が薄れ続けるにつれて、この風の石はますます貴重になっているのです。\n\nこの地から採れる役立つ物は、風の石だけではありません。どうぞ、この手引書を一冊お持ちください。", 0x2bcfca6e, 0xe8cd67c8, 0x3a9bfe02, 0x1c31b804, 0x7fc437ff, "....." },
  [93735] = { "壊れた構築体", "Valanaarの西側でRiaani Nightwindを見つけてください。", "歴史的に、Windshapersは風の精霊から授けられた魔法の器具や装置の手入れを担ってきました。島中にある無数の魔法の構造体もそうです。精霊たちが去って以来、そのうちまだ動くのはごくわずかです。\n\nValanaarでまだ動く数少ない構造体の一つが損傷してしまいました。職人の一人を助けに向かわせましたが、彼には手助けが必要かもしれません。街の西の端へ行き、できる限りの援助をしてください。", nil, "<Riaaniは機械の重い装甲板の下に顔を突っ込み、その下の仕掛けをいじろうとしている。あなたがいることにはまったく気づいていない。>\n\n嵐に呪われろ、コアはどこだ？！Gyrozephyrまで外そうなんて、誰が考えたんだ？この機械の風がまだ完全に消えていないのは奇跡だぞ！", 0x3b580ff6, 0xb230d6e2, 0x9c9b9f2d, nil, 0x121d9405, "...m." },
  [93736] = { "招かれざる霊", "Shadowgale ForestのWind Hollowsから、Wind Hollow Essencesを10個集めてください。", "Windshapersの最大の関心事は、精霊たちがなぜ我々のもとを去ったのか、そして彼らを連れ戻すために何ができるのかを、よりよく理解することです。北のShadowgale Forestの奇妙な特徴の一つに、「hollows」と呼ばれる不思議な風の精がいることがあります。彼らについても、なぜそこにいるのかについてもほとんど分かっていませんが、風の精霊が去った後に初めて現れ始めたことは分かっています。\n\nそこへ行き、彼らを散らしてください。その残骸を集めて、ここへ持ってきてください。", "Shadowgale Forestは危険な場所だ。幽霊が出ると言う者さえいる。私はそんなことは信じていないが、気の弱い者や備えのない者が行く場所ではないのは確かだ。", "このエッセンスを扱っていると……深い不安に襲われます。悪意に満ちた、悔恨のオーラがそこから漂ってくるのを感じるほどです。気が遠くなりそうです。\n\n<Endariaはかすかに身震いする。>\n\nこれ以上調べるのは気が進みません。", 0x4f4a02b2, 0x24071ed5, 0x120ac132, 0x720c2c52, 0x64b49c6f, "....." },
  [93737] = { "壊れた構築体", "Riaani Nightwindと話し、彼の話を聞いて下さい。", "ああ、どうも。Ayessaが手伝いによこしたって？ それならいいか。\n\n君みたいな見るからに素人に何ができるか分からないが、この構造体の中身から頭を引っこ抜くまで少し待ってくれれば、手伝ってもらえそうなことをいくつか思いつくかもしれない。", "この構造物から、なぜわざわざこの部品を盗もうとする者がいるのか想像もつかない。gyrozephyr以外では、これらの部品に実用的な使い道はほとんどない。そのgyroでさえ、本来の目的以外ではほとんど役に立たないだろう。", "材料を集めてきてくれてありがとう。中には手に入れるのがかなり大変な物もあっただろう。\n\nこの部品があれば、あの機械をまた動かせる。あとは記憶が無事で、誰が部品を持ち去ったのかを教えてくれることを願うだけだ。", 0x3b580ff6, 0x20bf5d1d, 0xc9fcddd9, 0x57705db0, 0xf88bb130, "....." },
  [93738] = { "壊れた構築体", "ValanaarのAyessa Dawnsingerのところへ戻って報告してください。", "Brightwishだと？つまりHigh Orderは、何らかの理由でこれらの部品を取り除きたかったわけか。だが、いったいなぜだ？\n\nHigh Orderは昔から干渉好きで、いつも風の精霊の魔法で実験をしたがっている。奴らは度を越して大胆で、Windshaperの管轄にある知識に手を出すことは固く禁じてきたのだが、最近は我々の忍耐を試すようなことばかりしている。\n\n分かったことをAyessa Dawnsingerに報告するといい。この先どうすべきか、彼女が指示してくれるだろう。", nil, "実に興味深い。では、機械が壊れたのはHigh Orderのせいだったと？\n\nBelathaanのことは知っている。Valennia Stormfistのいとこで、実は母親はWindshaperだった。彼がこれに関わっていたとは残念だ。\n\n少し考えさせてくれ。", 0x3b580ff6, 0x29d7b548, 0x98b46a4e, nil, 0xe4724d1e, "...m." },
  [93739] = { "Hordeを探る", "Grommash HoldのNazgrelと話し、さらなる指示を受けてください。受けた指示に従って、Vol'jin、Cairne Bloodhoof、Lady Sylvanas Windrunnerを探し出して話してください。", "Azerothは広大な世界で、Hordeの領土も広い。Undercity、Orgrimmar、Thunder Bluffには、それぞれまったく独特な民と文化がある。\n\nここAzerothでHordeの客人となるのなら、我らの首都を順に一つずつ訪ねておくとよいだろう。道順は私の相談役のNazgrelに聞くがいい。", nil, "戻ってきたのですね。旅で多くを学べたことを願っています。\n\n私の知る限り、あなたの同胞はまだMulgoreで足場を固めているところです。彼らを待つ間、Orgrimmar周辺の地を探索してみてはどうでしょう。特にBarrensは、あなたのような意欲ある冒険者をいつでも必要としています。", 0x7968676a, 0x9721d08e, 0xc1326b85, nil, 0x9b3fc549, "...m." },
  [93740] = { "血には血を", "Gustberry LowlandsのAl'Akethの信者の死体から、Al'Aketh Windstone Charmsを10個集めてください。", "今朝、Windshaperの見習いたちが何人もHighlandsで死んでいるのが見つかった。確かなことは言えないが、Al'Akethの仕業である可能性が高い。Windshapersは、血には血で報いる。必ずだ。\n\n北へ向かい、出会ったAl'Akethを片っ端から倒せ。その証として、奴らのwindstone prayer charmsを持ってこい。我々は許さないし、忘れない。", "Al'Akethはあまりにも長く血塗られた狂信を続けてきた。これは奴らが受ける報いの始まりにすぎない。", "<風の石のお守りを手渡すと、Ayessaは動揺し、どこか上の空の様子だ。>\n\n私のことは気にしないで、{name}。今日はただ……つらい一日だったというだけです。これまでのwindshapersへの尽力に感謝します。", 0x8fdc4a0a, 0xc45880fd, 0xe1adb7e7, 0xe653122a, 0x7adc4448, "....." },
  [93746] = { "断固たる対応", "Shrine of Akirへ向かう道沿いでBelathaan Brightwishと対決して下さい。", "High Orderには、Windshaperの問題に首を突っ込めばどうなるか警告してある。Belathaanを見せしめにして、いくつか痣をつけて、我々の定めた境界への健全な敬意を植え付けたうえでHigh Orderへ送り返すべきだと思う。\n\nBelathaanは町を出て、北のShrine of Akirへ向かうところを見られている。なぜそこへ向かったのかは分からないが、道中で一人のところを問い詰めるのが最も安全だ。彼を見つけて、心に少し恐怖を植え付けてやれ。", nil, "待って、何ですって？！Belathaanが……死んだ？\n\n<起きたことを話すと、Ayessaは耳を傾ける。>\n\nHigh OrderがAl'Akethと会って和平を話し合っていた？教団との和平などありえません。彼らは人殺しの狂信者です。Belathaanを一人で交渉に行かせるなんて、Elaadrinは何を考えていたのでしょう？\n\n気にしないで、{name}。これはあなたのせいではありません。またしても、High Orderの傲慢さが悪いのです。あなたはただ、正しい場所に間の悪い時に居合わせただけです。", 0x2e10a415, 0x87bb368c, 0x049e9393, nil, 0x348cc12c, "...m." },
  [93791] = { "Belannとの対話", "ValanaarのBelann Windwoodと話してください。", "{name}、あなたの魔法の腕が上がっているのは明らかです。若く志あるメイジのための、High Orderの最も古い伝統の一つに参加する時が来たと思います。あなた自身の呪文の触媒を作る時です。\n\nValanaarのBelann Windwoodを訪ねてください。彼は一世紀以上もHigh Orderのために杖やワンドを作ってきましたから、安心して任せられます。", nil, "ああ、あなたが{name}ですね？我々のしきたりと歴史を熱心に学ぼうとする若いメイジを見ると、心強く思います。さあ、あなたの呪文の焦点具を作る次の手順を説明しましょう。", 0x9eee1307, 0xdac9b99f, 0x9e12128a, nil, 0x293bd11b, "...m." },
  [93797] = { "風に揺れる枝", "Wind-Infused BoughをValanaarのBelann Windwoodに届けてください。", "ある程度の魔法の熟練を示した若いメイジが、自分自身の呪文の触媒を作るのは、昔ながらの伝統だ。これは普通、我らの最も古い木々から落ちた枝を集めて行う。そうした木々には風の元素の痕跡がわずかに残っているからね。\n\n最も理想的な枝は、Falaath Villageのすぐ南にある風の祠の近くにあると分かった。行って大きな枝を持ってきてくれれば、君の呪文の触媒を作りながら伝統について教えよう。", "Zephrasでは年を追うごとに、魔法の才に恵まれた者がどんどん少なくなっています。\n\nあなたのような若いメイジが、私たちの最も古い伝統に加わり、歴史と文化を守り続ける手助けをしてくれるのを見られて嬉しく思います。", "ありがとう、{name}。この大枝には、才能ある者に使いこなされるのを待つ元素の力が確かに感じられます。素晴らしい呪文の焦点具になるでしょう。\n\nもしかして、この枝があなたに歌いかけてきましたか？枝が{class}を選ぶのであって、その逆ではない、ということはよくあるのです。\n\n<Belannはくすくす笑いながら、あなたの手からそっと大枝を受け取る。>", 0x53b7cabb, 0xbb3c4f26, 0x55b3e7d7, 0xf0384662, 0x12ab22f5, "....." },
  [93835] = { "Lorthunaとの対決", "頭上のRohashi Spiresへ通じるポータルを使い、High Priestess Lorthunaと対峙するElaadrin EvengaleとAyessa Dawnsingerに加わってください。", "Lorthunaは何かのポータルを使って上の尖塔へ逃げた。AyessaとElaadrinが後を追って入っていった。ほんの少し前のことだ。\n\nすまないが、攻撃を1発多く食らいすぎた。私はここまでだ。ポータルを抜けて、Elaadrinを見つけ、彼らがLorthunaを止めるのを手伝ってくれ。\n\nElaadrinとAyessaが呼んだという援軍がすぐに来ない限り、ここからは君一人だ。幸運を、{class}。", nil, "Valenniaと部隊も無事に逃げられるよう、残っているメイジを何人か送りました。彼女は今、High Elder Shadowsongの住まいで休んでいるはずです。\n\nAnsiremはAzerothへ戻らねばなりませんでしたが、発つ前にHigh Orderの次の手立てについて彼と話し合いました。今日は生き延びましたが、Zephrasは今、危険なほど無防備です。これから来るものに備えて計画を立てねばなりません。", 0x90290d9d, 0x21f66bcc, 0xcf4192f2, nil, 0x2047cb19, "...m." },
  [93836] = { "Zephrasの運命", "ValanaarのTalaanis Shadowsongと話してください。", "Mulnはエレメンタルの王たちについて多くを語ってくれたが、我々にはAl'Akirを恐れるだけの十分な理由があるようだ。Zephrasを彼の目から隠していた結界が消えた今、我々はまったくの無防備だ。彼が攻撃してくると決めたなら、彼自身の領域であるここでは、我々に勝ち目はない。\n\nHigh Elder Shadowsongは、我々が置かれている危険と、何より、Azerothへの任務における我々の意図を知る必要がある。我々は故郷を救う手立てを見つけ出す。誓おう。", nil, "<Shrine of Akirの上で起きたこと、そしてZephras Isleを去るというAyessaの計画を話すと、Talaanis Shadowsongはじっと耳を傾ける。>\n\nさらに考えねばならぬが、良い面を見れば、我らはLorthunaを退け、教団から指導者を奪った。我らの故郷はまだ侵されてはおらぬ。元素の神々の時の流れからすれば、Al'Akirが我らに目を向けるまでには何年も……いや、何十年もかかるやもしれぬ。\n\n今は恐れるべきことも多いが、祝うべきことも多いのだ。", 0x6d3ea2fe, 0x4440ff8a, 0x7c6d6603, nil, 0xa70add28, "...m." },
  [93862] = { "木箱の返却", nil, nil, nil, nil, 0xeb410c2b, nil, nil, nil, nil, ".mmmm" },
  [93926] = { "西の見張り", "西の見張り塔でPeacekeeper Vaanielを見つけてください。", "教団が塔を襲う理由が何であれ、そのために我々の仲間を失う価値はない。\n\n南西へ向かって、あの見張り塔の様子を確かめてきてほしい。そこにいる治安維持隊を見つけて、村へ引き返すよう伝えてくれ。あの塔を守り抜くことは、それで失われる命に見合わない。それよりも、今いる守備兵をここに集めて市民を守りたい。\n\n指揮を執っているのはPeacekeeper Vaanielだ。できるだけ早くここへ戻るよう伝えてくれ。急げ！", nil, "<ここにある遺体はまだ比較的新しく、殺されてからそれほど経っていないのは明らかだ。この治安部隊員の肌に残る火傷と焦げ跡からすると、教団の嵐を操る呪文使いたちに殺されたのは明らかだ。>", 0x18869d4a, 0xc19f2264, 0x3e46d2b0, nil, 0x1742715f, "...m." },
  [93927] = { "最後の頼み", "死んだ平和維持官のそばで見つけた書き付けを拾い、それを読んで次にすべきことを決めてください。", "<死んだ治安維持隊員の遺体を調べていると、血に濡れたメモがその手から落ちた。拾って読めば、ここからどうすべきか手がかりが得られるかもしれない。>", "西の見張り所から何か知らせは？", "では、全員死んだのか。教団のくそったれどもに嵐の呪いあれ！\n\nあなたは司祭を倒し、塔の教団員たちを止めてくれたが、正直に言うと、奴らが柱に何かをしていたというあなたの話が、今は二重に気がかりだ。あれほど大量の風の石が奴らのところに蓄えられていたということは、そのために膨大なエネルギーが必要だったということだ。\n\n考えずにはいられない。奴らの最終的な狙いは何だ？柱を冒涜し、村を襲う？何のために？", 0x96fa8046, 0xf1e8b9e6, 0xc18d4d9f, 0x3a64b789, 0xad2ad512, "....." },
  [93928] = { "ネズミとミルク", "ネズミにクッキーを取ってきてあげてください。", "クッキーがほしいんだ、分かるか？\n\nへっ！", nil, nil, 0x4a4cc954, 0xaadb1f71, 0xe2b329a9, nil, nil, "...mm" },
  [93948] = { "印章の配達", "Shadowsong Family SignetをValanaarのTalaanis Shadowsongに届けてください。", "どうせValanaarへ行くのなら、塔で取り戻した印章指輪をValanaarのTalaanis Shadowsongに届けてください。\n\n彼はこれを取り戻したいでしょうし、何より、甥の身に何があったのか知りたいはずです。TalaanisはZephras IsleのHigh Elderであり、何より、今の苦難にもかかわらず民に深く愛されている善き人です。この知らせに彼がどう反応するかを思うと胸が痛みます。彼の喪失にお悔やみを伝えてください。", "私に何を持ってきたんだ？ああ……なんてことだ。", "私の……甥が死んだとは、本当に残念です。これを取り戻し、私のもとへ届けてくれたことに心から感謝します。\n\nあなたほど有能な若いshen'doreiが高地から下りてくることはめったにありません。仕事が必要なら、ここValanaarの治安部隊の隊長、Valennia Stormfistと話してください。近頃は、得られる助けはすべて必要なのです。", 0x95398690, 0x57f7b4b1, 0xba89a78d, 0x93229de8, 0x0454cabb, "....." },
  [93949] = { "虫にやられて", "ValanaarでSkyhopperを倒し、Enchanted Skyhopperを$N1体始末する。", "盗聴されていたんだ。\n\n低地は今skyhopperの季節で、つまりそこら中にこの害虫がいる。High Orderのメイジの一人が、倒した虫の一匹に何かの付呪がかけられていたと報告してきた。よく調べてみると、盗み聞きの呪文の一種らしい。\n\n教団がこの付呪された虫を密偵として使っているのではないかと我々は疑っている。行って駆除してきてくれ。見た目ではどれが付呪されているか分からないから、全部倒すしかない。", nil, "Valanaarの周りにはこういう小さな生き物がまだいるに違いないが、魔法をかけられたskyhopperを踏みつぶすたびに、街はほんの少し安全になる。", 0xebc83872, 0xf0db79e8, 0x5a7063fe, nil, 0xf7ae869a, "...m." },
  [93951] = { "ささやかな美", "Shen'dar HighlandsでHippogryph Downの羽根を8枚集めてください。", "村の南西に住み着いたヒッポグリフたちは厄介者になることもありますが、その羽根を手に入れるまたとない機会でもあります。skyborneの多くは鮮やかな羽根で髪を飾るのが大好きで、ヒッポグリフの綿毛はとりわけ鮮やかで、何より絹のように柔らかいのです。\n\nそちらへ向かうなら、巣のまわりに落ちている羽根をできるだけたくさん集めてみてください。野生のヒッポグリフはよそ者に寛容ではないので、どうか気をつけて。", "どんな素敵なものを持ってきてくれたの？", "髪飾りのために羽根を集めるなんて、ちょっとした虚栄の些事に見えるかもしれません。けれど、こんな時だからこそ、小さな喜びをできるだけ大切にする必要があるのです。\n\n私の作った物がひとつでも誰かに喜びをもたらすなら、それは良い一日だったと思えます。これを持ってきてくれて、Zephrasに喜びを届ける手伝いをしてくれてありがとう。", 0xfb24871b, 0xf83626f8, 0x2b37a842, 0x1bd026f8, 0x6c68b48e, "....." },
  [93958] = { "奥の聖域", "Shrine of Akirの内陣にいるValennia Stormfistと話してください。", "Valenniaの部隊がたった今、内なる聖域に突入した。最初は中で激しい戦いになっていたが、今は……不気味なほど静かになった。中へ入って、Valenniaと彼女の部隊に合流できるよう最善を尽くしてくれ……まだ誰か残っていればだが。\n\n私はここに残って、君の背後を守る。", nil, "<Valenniaはひどい傷を負っているようだ。>", 0x757fc20c, 0xb9c9ad7e, 0xfe6de4be, nil, 0x3a2cf55d, "...m." },
  [93963] = { "Allianceを探る", "Stormwind KeepのRandal Emersonと話し、さらなる指示を受けてください。受けた指示に従って、King Magni Bronzebeard、High Tinker Mekkatorque、Tyrande Whisperwindを探し出して話してください。", "Stormwind、Ironforge、Darnassusには、それぞれ独自の民と文化があります。ここAzerothのAllianceの客人として、我々の首都を順に訪ねる時間を取るとよいでしょう。\n\nまずは南の控えの間にいるRandal Emersonに道を聞いてください。", nil, "ああ、戻ったのですね。\n\nあなたの冒険が、この世界の広大さと驚異を感じさせてくれたことを願っています。圧倒されるように思えるでしょうが、同胞を助けるつもりなら、Azerothにいる間に何が降りかかろうと備えておかねばなりません。\n\nあなたの結社がDalaranで足場を固めるのを待つ間、Stormwind周辺の地に目を向けてみてはどうでしょう。特にWestfallは、その気があるなら、力を貸してくれる強い冒険者をいつでも歓迎しています。", 0xb5c2bf15, 0x80cbe7b7, 0x7db457d1, nil, 0xd5e8b7c2, "...m." },
})
